            </div>
            <div style={{ fontFamily: 'var(--font-share-tech-mono), monospace', fontSize: '10px', color: COLORS.textMuted, lineHeight: 1.6 }}>
              Three agents ready.<br />
              ARCHITECT ◇ DISRUPTOR ◆ REALIST ◈<br /><br />
              Enter a topic and execute to deploy.
            </div>
          </div>
        )}

        {/* Bottom spacer */}
        <div className="h-4" />
      </div>
    </div>
  );
}

